baseFiles.cache.js:
export function cached(map, key, compute) {
  if (map.has(key)) return map.get(key);
  const value = compute();
  map.set(key, value);
  return value;
}

patchFiles.cache.js:
export function cached(map, key, compute) {
  const prior = map.get(key);
  if (prior !== undefined || map.has(key)) return prior;
  const value = compute();
  map.set(key, value);
  return value;
}

